display.text:
use ruff_diagnostics::{AlwaysFixableViolation, Diagnostic, Edit, Fix};
use ruff_macros::{derive_message_formats, ViolationMetadata};
use ruff_python_parser::TokenKind;
use ruff_text_size::{TextRange, TextSize};

use crate::checkers::logical_lines::LogicalLinesContext;
use crate::rules::pycodestyle::rules::logical_lines::{DefinitionState, LogicalLine, TokenFlags};

/// ## What it does
/// Checks for missing whitespace around the equals sign in an unannotated
/// function keyword parameter.
///
/// ## Why is this bad?
/// According to [PEP 8], there should be no spaces around the equals sign in a
/// keyword parameter, if it is unannotated:
///
/// > Don’t use spaces around the = sign when used to indicate a keyword
/// > argument, or when used to indicate a default value for an unannotated
/// > function parameter.
///
/// ## Example
/// ```python
/// def add(a = 0) -> int:
///     return a + 1
/// ```
///
/// Use instead:
/// ```python
/// def add(a=0) -> int:
///     return a + 1
/// ```
///
/// [PEP 8]: https://peps.python.org/pep-0008/#whitespace-in-expressions-and-statements
#[derive(ViolationMetadata)]
pub(crate) struct UnexpectedSpacesAroundKeywordParameterEquals;

impl AlwaysFixableViolation for UnexpectedSpacesAroundKeywordParameterEquals {
    #[derive_message_formats]
    fn message(&self) -> String {
        "Unexpected spaces around keyword / parameter equals".to_string()
    }

    fn fix_title(&self) -> String {
        "Remove whitespace".to_string()
    }
}

/// ## What it does
/// Checks for missing whitespace around the equals sign in an annotated
/// function keyword parameter.
///
/// ## Why is this bad?
/// According to [PEP 8], the spaces around the equals sign in a keyword
/// parameter should only be omitted when the parameter is unannotated:
///
/// > Don’t use spaces around the = sign when used to indicate a keyword
/// > argument, or when used to indicate a default value for an unannotated
/// > function parameter.
///
/// ## Example
/// ```python
/// def add(a: int=0) -> int:
///     return a + 1
/// ```
///
/// Use instead:
/// ```python
/// def add(a: int = 0) -> int:
///     return a + 1
/// ```
///
/// [PEP 8]: https://peps.python.org/pep-0008/#whitespace-in-expressions-and-statements
#[derive(ViolationMetadata)]
pub(crate) struct MissingWhitespaceAroundParameterEquals;

impl AlwaysFixableViolation for MissingWhitespaceAroundParameterEquals {
    #[derive_message_formats]
    fn message(&self) -> String {
        "Missing whitespace around parameter equals".to_string()
    }

    fn fix_title(&self) -> String {
        "Add missing whitespace".to_string()
    }
}

/// E251, E252
impl DefinitionState {
    pub(crate) fn whitespace_around_named_parameter_equals(
        &mut self,
        line: &LogicalLine,
        context: &mut LogicalLinesContext,
    ) {
        let line_info = line.line;
        if line_info.tokens_start >= line_info.tokens_end {
            return;
        }
        if !line_info.flags.contains(TokenFlags::OPERATOR) {
            return;
        }

        let tokens =
            &line.lines.tokens[line_info.tokens_start as usize..line_info.tokens_end as usize];
        let locator = line.lines.locator;

        let mut parens = 0u32;
        let mut fstrings = 0u32;
        let mut annotated_func_arg = false;
        let mut prev_end = TextSize::default();
        let mut iter = tokens.iter().peekable();

        while let Some(token) = iter.next() {
            let kind = token.kind();
            self.visit_token_kind(kind);
            match kind {
                TokenKind::NonLogicalNewline => continue,
                TokenKind::FStringStart => fstrings += 1,
                TokenKind::FStringEnd => fstrings = fstrings.saturating_sub(1),
                TokenKind::Lpar | TokenKind::Lsqb => {
                    parens = parens.saturating_add(1);
                }
                TokenKind::Rpar | TokenKind::Rsqb => {
                    parens = parens.saturating_sub(1);
                    if parens == 0 {
                        annotated_func_arg = false;
                    }
                }
                TokenKind::Colon if parens == 1 && self.in_function_definition() => {
                    annotated_func_arg = true;
                }
                TokenKind::Comma if parens == 1 => {
                    annotated_func_arg = false;
                }
                TokenKind::Equal if self.in_type_params() || (parens > 0 && fstrings == 0) => {
                    let token_range = token.range;
                    let token_start = token_range.start();
                    let token_end = token_range.end();
                    if self.in_type_params() || (annotated_func_arg && parens == 1) {
                        let before = if token_start >= prev_end {
                            locator.slice(TextRange::new(prev_end, token_start))
                        } else {
                            " "
                        };
                        if before.is_empty() && prev_end != TextSize::new(0) {
                            let mut diagnostic = Diagnostic::new(
                                MissingWhitespaceAroundParameterEquals,
                                token_range,
                            );
                            diagnostic.set_fix(Fix::safe_edit(Edit::insertion(
                                " ".to_string(),
                                token_start,
                            )));
                            context.push_diagnostic(diagnostic);
                        }

                        while let Some(next) = iter.peek() {
                            if next.kind() == TokenKind::NonLogicalNewline {
                                iter.next();
                            } else {
                                let next_start = next.range.start();
                                let after = if next_start >= token_end {
                                    locator.slice(TextRange::new(token_end, next_start))
                                } else {
                                    " "
                                };
                                if after.is_empty() {
                                    let mut diagnostic = Diagnostic::new(
                                        MissingWhitespaceAroundParameterEquals,
                                        token_range,
                                    );
                                    diagnostic.set_fix(Fix::safe_edit(Edit::insertion(
                                        " ".to_string(),
                                        token_end,
                                    )));
                                    context.push_diagnostic(diagnostic);
                                }
                                break;
                            }
                        }
                    } else {
                        let before = if token_start >= prev_end {
                            locator.slice(TextRange::new(prev_end, token_start))
                        } else {
                            " "
                        };
                        if !before.is_empty() {
                            let mut diagnostic = Diagnostic::new(
                                UnexpectedSpacesAroundKeywordParameterEquals,
                                TextRange::new(prev_end, token_start),
                            );
                            diagnostic
                                .set_fix(Fix::safe_edit(Edit::deletion(prev_end, token_start)));
                            context.push_diagnostic(diagnostic);
                        }

                        while let Some(next) = iter.peek() {
                            if next.kind() == TokenKind::NonLogicalNewline {
                                iter.next();
                            } else {
                                let next_start = next.range.start();
                                let after = if next_start >= token_end {
                                    locator.slice(TextRange::new(token_end, next_start))
                                } else {
                                    " "
                                };
                                if !after.is_empty() {
                                    let mut diagnostic = Diagnostic::new(
                                        UnexpectedSpacesAroundKeywordParameterEquals,
                                        TextRange::new(token_end, next_start),
                                    );
                                    diagnostic.set_fix(Fix::safe_edit(Edit::deletion(
                                        token_end, next_start,
                                    )));
                                    context.push_diagnostic(diagnostic);
                                }
                                break;
                            }
                        }
                    }
                }
                _ => {}
            }

            prev_end = token.range.end();
        }
    }
}

